/* Original MIS 465 educational simulation. No server calls, payment SDKs, or credentials. */
(() => {
  'use strict';
  const seed = window.BB_SEED;
  const state = BB.load(seed);
  const $ = (s, root = document) => root.querySelector(s);
  const main = $('#main'), modal = $('#modal'), content = $('#modal-content');
  const countries = ['China', 'USA', 'UK', 'India'];
  const flags = {China:'🇨🇳',USA:'🇺🇸',UK:'🇬🇧',India:'🇮🇳'};
  const categories = ['All products','Electronics','Lifestyle','Fashion','Beauty','Home'];
  const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money = n => '৳' + Math.round(n).toLocaleString('en-US');
  const product = id => seed.products.find(p => p.id === id);
  const arrow = '<span aria-hidden="true">↗</span>';
  const icon = (name, cls='') => `<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${({search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',box:'<path d="m3 7 9-5 9 5v11l-9 4-9-4V7Z"/><path d="m3 7 9 5 9-5M12 12v10M7 4.8l10 4.4"/>',shield:'<path d="M12 2 3 6v7c0 5 9 9 9 9s9-4 9-9V6l-9-4Z"/><path d="m8 12 3 3 5-6"/>',plane:'<path d="m2 15 8-3L7 3l3-1 5 8 5-2c4-1 4 2 1 3l-5 2 1 8-2 1-4-7-6 2-3-2Z"/>',bag:'<path d="M4 8h16l1 14H3L4 8ZM8 8V6a4 4 0 0 1 8 0v2"/>',globe:'<circle cx="12" cy="12" r="10"/><ellipse cx="12" cy="12" rx="4.5" ry="10"/><path d="M2 12h20M4 6h16M4 18h16"/>',check:'<path d="m5 12 4 4L20 5"/>'})[name] || ''}</svg>`;
  let origin = 'China', route = 'home', toastTimer, lastFocus, viewAdmin = false;
  let shop = {category:'All products',origin:'All origins',sort:'featured',query:''};
  let dash = {query:'',status:'all'};
  const persist = () => { const saved=BB.save(state); if (!saved) toast('Browser storage is unavailable. This session still works; changes may reset on reload.'); updateBag(); return saved; };
  const saveAndToast = msg => { if(persist()) toast(msg); };
  function toast(msg) { clearTimeout(toastTimer); $('#toast').textContent = msg; $('#toast').hidden=false; toastTimer=setTimeout(()=>{$('#toast').hidden=true;},4200); }
  function updateBag() { const count=state.cart.reduce((a,b)=>a+b.quantity,0); $('#bag-count').textContent=count; $('.bag-button').setAttribute('aria-label',`Open shopping bag, ${count} items`); }
  function options(items, selected) { return items.map(i=>`<option value="${esc(i)}" ${i===selected?'selected':''}>${esc(i)}</option>`).join(''); }
  function art(p) {
    const shape = {
      P001:`<path d="M68 113V86c0-74 104-74 104 0v27" fill="none" stroke="#394e46" stroke-width="20"/><path d="M68 100V85c0-63 104-63 104 0v15" fill="none" stroke="#e6e4d8" stroke-width="12"/><g transform="rotate(-12 70 122)"><rect x="48" y="91" width="36" height="72" rx="17" fill="#344b41"/><rect x="53" y="94" width="24" height="65" rx="11" fill="#849b75"/></g><g transform="rotate(12 170 122)"><rect x="156" y="91" width="36" height="72" rx="17" fill="#344b41"/><rect x="162" y="94" width="24" height="65" rx="11" fill="#849b75"/></g>`,
      P002:`<g transform="translate(23 59) rotate(-11 95 45)"><rect width="194" height="92" rx="10" fill="#b6b9ad"/><rect y="-6" width="194" height="88" rx="10" fill="#f5f2e8"/>${Array.from({length:4},(_,r)=>Array.from({length:12},(_,c)=>`<rect x="${8+c*15}" y="${4+r*17}" width="12" height="13" rx="2" fill="${r===3&&c>3&&c<8?'#bbbdae':c===11?'#8ba081':'#deded3'}"/>`).join('')).join('')}<rect x="63" y="55" width="70" height="13" rx="2" fill="#b8c0ad"/></g>`,
      P003:`<g transform="rotate(-9 120 105)"><rect x="44" y="61" width="154" height="103" rx="16" fill="#55645f"/><rect x="44" y="71" width="154" height="52" fill="#b7c2bb"/><rect x="65" y="51" width="33" height="14" rx="4" fill="#63756a"/><circle cx="126" cy="113" r="42" fill="#d9dcd0"/><circle cx="126" cy="113" r="33" fill="#263e3a"/><circle cx="126" cy="113" r="23" fill="#465e5d"/><circle cx="126" cy="113" r="13" fill="#173b3b"/><circle cx="118" cy="105" r="7" fill="#8ca6a0"/><rect x="166" y="80" width="20" height="12" rx="3" fill="#e1e5da"/></g>`,
      P004:`<path d="M83 79V60c0-48 76-48 76 0v19" fill="none" stroke="#9a8964" stroke-width="10"/><path d="m56 66 128 3 12 105H44Z" fill="#d3bf94"/><path d="m63 72 112 2 10 91H53Z" fill="#e1cfa7"/><path d="M84 66v69M158 67v68" stroke="#b8a37e" stroke-width="7"/><path d="M96 113h49v29H96Z" fill="#c3af86"/><text x="120" y="132" text-anchor="middle" font-size="8" fill="#756f56" font-family="sans-serif">NORTH & NOON</text>`,
      P005:`<path d="M102 38c0-20 36-20 36 0" fill="none" stroke="#52644c" stroke-width="8"/><rect x="66" y="30" width="108" height="155" rx="33" fill="#657b59"/><path d="M78 46c20-15 65-15 84 0" fill="none" stroke="#8d9e7f" stroke-width="4"/><rect x="75" y="103" width="90" height="68" rx="15" fill="#526c4d"/><path d="M83 116h74" stroke="#9dac8e" stroke-width="3"/><rect x="108" y="64" width="25" height="22" rx="3" fill="#c2c6ad"/>`,
      P006:`<g transform="rotate(-12 120 114)"><path d="M43 108 62 69l36 15 32 21 52 9c14 3 20 17 14 30H45c-14-7-14-23-2-36Z" fill="#e8e4cf"/><path d="M40 135h158v17H40c-12-5-12-13 0-17Z" fill="#f6f3e7"/><path d="m78 87 44 25M71 97l43 22M65 108l36 19" stroke="#b4bdab" stroke-width="4"/><path d="m50 107 17 18" stroke="#c4cbb8" stroke-width="3"/></g>`,
      P007:`<path d="m82 38 25-11h26l25 11 38 36-25 28-18-18 5 103H82l5-103-18 18-25-28Z" fill="#8ca17b"/><path d="m107 27 13 26 13-26 10 12-23 26-23-26Z" fill="#6c8761"/><path d="M120 60v127" stroke="#bbc8a7" stroke-width="3"/><path d="M137 73h18v25h-18Z" fill="#7e966b"/><g fill="#d1d9c3"><circle cx="126" cy="80" r="2"/><circle cx="126" cy="104" r="2"/><circle cx="126" cy="128" r="2"/><circle cx="126" cy="152" r="2"/></g>`,
      P008:`<path d="M59 125c-8-85 117-105 128-15l-18 27-110-12Z" fill="#b4b493"/><path d="M117 51c-10 24-11 51-7 77" stroke="#d5d4ba" stroke-width="2" fill="none"/><path d="m59 115 126-4c-15 53-117 65-150 43-22-14 6-29 24-39Z" fill="#9b9e7e"/><path d="M71 124c49 18 86 9 110-6" fill="none" stroke="#c6c7aa" stroke-width="3"/>`,
      P009:`<rect x="104" y="24" width="31" height="42" rx="7" fill="#737c72"/><rect x="96" y="57" width="47" height="17" rx="5" fill="#c6bbaa"/><rect x="82" y="73" width="75" height="117" rx="15" fill="#a7a48d"/><rect x="88" y="104" width="63" height="56" rx="2" fill="#f5f0e5"/><text x="120" y="127" text-anchor="middle" fill="#747b67" font-size="12" font-family="serif">petal lab</text><text x="120" y="144" text-anchor="middle" fill="#747b67" font-size="7">DEW DAILY</text>`,
      P010:`<rect x="44" y="89" width="61" height="95" rx="13" fill="#c5bfa8"/><rect x="54" y="73" width="41" height="22" rx="4" fill="#8c9483"/><rect x="111" y="57" width="50" height="127" rx="10" fill="#ede0c5"/><rect x="121" y="40" width="30" height="22" rx="3" fill="#8a9381"/><rect x="170" y="99" width="31" height="85" rx="9" fill="#a1ae92"/><rect x="174" y="86" width="23" height="18" rx="3" fill="#e7ddc5"/><path d="M53 121h43v37H53ZM118 99h36v54h-36Z" fill="#f8f3e8"/><text x="135" y="121" text-anchor="middle" font-size="8" fill="#7a8a6d">SOFT</text><text x="135" y="134" text-anchor="middle" font-size="8" fill="#7a8a6d">RITUAL</text>`,
      P011:`<ellipse cx="115" cy="183" rx="55" ry="10" fill="#97a088"/><path d="M116 178V55c0-37 65-37 65 0" fill="none" stroke="#77846b" stroke-width="9"/><path d="m154 48-13 38h66l-12-38Z" fill="#c9cbb6"/><ellipse cx="174" cy="85" rx="33" ry="8" fill="#f5efcb"/><path d="m153 90-18 83h80l-21-83Z" fill="#ebebc2" opacity=".25"/>`,
      P012:`<path d="M151 82h17c45 0 43 68 1 68h-18" fill="none" stroke="#7f9174" stroke-width="15"/><path d="M64 65h98v95c0 35-98 35-98 0V65Z" fill="#a6b198"/><ellipse cx="113" cy="65" rx="49" ry="13" fill="#c9d0ba"/><ellipse cx="113" cy="65" rx="39" ry="8" fill="#5d715a"/><path d="M86 89v64" stroke="#bbc5ac" stroke-width="5" stroke-linecap="round"/>`
    }[p.id];
    return `<svg viewBox="0 0 240 220" aria-hidden="true"><ellipse cx="122" cy="194" rx="73" ry="8" fill="#243b2e" opacity=".07"/>${shape||''}</svg>`;
  }
  function heroArt() { return `<svg viewBox="0 0 600 470" role="img" aria-label="Illustrated parcels and global shipping routes to Bangladesh"><defs><radialGradient id="globe"><stop stop-color="#e8f0db"/><stop offset="1" stop-color="#dbe8cd"/></radialGradient><linearGradient id="boxfront" x2="1" y2="1"><stop stop-color="#cfad73"/><stop offset="1" stop-color="#b68b55"/></linearGradient><linearGradient id="boxside" x2="1" y2="1"><stop stop-color="#a77e4d"/><stop offset="1" stop-color="#8f653b"/></linearGradient></defs><circle cx="321" cy="218" r="178" fill="url(#globe)"/><g fill="none" stroke="#c0d2ad" stroke-width="1" opacity=".65"><ellipse cx="321" cy="218" rx="88" ry="178"/><ellipse cx="321" cy="218" rx="145" ry="178"/><ellipse cx="321" cy="218" rx="177" ry="66"/><ellipse cx="321" cy="218" rx="177" ry="128"/><path d="M143 218h356M321 40v356"/></g><g fill="#b3c89b" opacity=".65"><path d="m204 102 45-26 23 15-4 22 30 12-8 28-25 17-14 48-26 5-24-30-25-6-12-36 21-22Z"/><path d="m274 217 26 6 19 31-14 17 4 24-23 43-17-14-5-39-15-24Z"/><path d="m348 108 45-25 30 29 41 13 12 39-24 4-20 26-34-14-20 19-4 38-24-9-14-30 6-25-16-27Z"/><path d="m370 225 25-13 24 22-8 47-21 21-18-34Z"/><path d="m437 286 31 4 15 23-17 20-37-13Z"/></g><g fill="none" stroke="#58875d" stroke-width="1.6" stroke-dasharray="5 7"><path d="M180 176Q299-14 439 221"/><path d="M438 221Q531 369 324 374"/><path d="M438 221Q338 100 296 133"/></g><circle cx="439" cy="221" r="12" fill="#2b6b45" opacity=".12"/><circle class="route-dot" cx="439" cy="221" r="5" fill="#2b6b45"/><circle cx="180" cy="176" r="5" fill="#5e8b5d"/><circle cx="296" cy="133" r="4" fill="#5e8b5d"/><g transform="translate(319 52) rotate(31)"><path d="m0 22 25-7L22 0l5-1 12 13 16-4c7-1 8 5 1 7l-16 5 1 17-4 1-8-16-25 6Z" fill="#123f36"/></g><ellipse cx="285" cy="414" rx="146" ry="20" fill="#244b3510"/><g transform="translate(155 246)"><path d="m0 39 115-39 100 48-113 43Z" fill="#dec28e"/><path d="m0 39 102 52v119L0 153Z" fill="url(#boxfront)"/><path d="m102 91 113-43v115l-113 47Z" fill="url(#boxside)"/><path d="m53 21 105 49-19 7L35 28Z" fill="#f1dcb0"/><path d="M139 77v42l19-8V70Z" fill="#d7bd89"/><path d="m18 100 64 32v34l-64-33Z" fill="#f3ead4"/><path d="m26 115 45 23M26 121l32 16" stroke="#8d927c" stroke-width="2"/><text x="49" y="153" text-anchor="middle" font-family="sans-serif" font-size="8" fill="#4a6651" transform="rotate(27 49 153)">BongoBridge.</text><path d="m156 155 22-9m-11-5v20" stroke="#d4bd91" stroke-width="3"/></g><g transform="translate(341 262) scale(.68)"><path d="m0 39 115-39 100 48-113 43Z" fill="#d4e2be"/><path d="m0 39 102 52v119L0 153Z" fill="#adc293"/><path d="m102 91 113-43v115l-113 47Z" fill="#7f9d71"/><path d="m53 21 105 49-19 7L35 28Z" fill="#e4ebcc"/><path d="M139 77v42l19-8V70Z" fill="#bbce9e"/><path d="m22 105 53 26v33l-53-28Z" fill="#e8eddb"/></g><circle cx="491" cy="100" r="4" fill="#acbe92"/><circle cx="130" cy="304" r="4" fill="#c3d3aa"/><path d="M501 311h12m-6-6v12M157 91h12m-6-6v12" stroke="#91ab7e" stroke-width="1.5"/></svg>`; }
  function cards(list) { return list.map(p=>`<article class="product-card"><div class="product-art" style="background:${p.accent}" data-action="product" data-id="${p.id}"><button class="product-tag" data-action="product" data-id="${p.id}" aria-label="View ${esc(p.name)}">${esc(p.tag)}</button>${art(p)}<span class="product-origin">${flags[p.origin]} ${p.origin}</span><button class="quick-add" data-action="add" data-id="${p.id}" aria-label="Add ${esc(p.name)} to bag">+</button></div><div class="product-body"><p class="product-brand">${esc(p.brand)}</p><h3><button data-action="product" data-id="${p.id}" style="padding:0;text-align:left">${esc(p.name)}</button></h3><div class="product-bottom"><span class="product-price">${money(p.price*120)} <small>item only</small></span><span class="product-weight">${p.weight} kg · sample</span></div></div></article>`).join(''); }
  function homePage() {
    main.innerHTML=`<section class="hero"><div class="hero-copy"><div class="eyebrow">Your bridge to global shopping</div><h1>The world is yours.<br>We bring it <em>home.</em></h1><p>Discover things you love from around the world. Shop, ship, and track their journey to Bangladesh — all in one place.</p><div class="hero-buttons"><a class="button dark" href="#shop">Explore global finds ${arrow}</a><button class="button outline" data-action="estimate">Estimate shipping ${arrow}</button></div><div class="hero-note">${icon('shield')}<span>One simple journey. From global stores to your door.</span></div></div><div class="hero-art">${heroArt()}<div class="floating-label hero-origin"><span class="round-icon" id="hero-flag">${flags[origin]}</span><div><strong id="hero-hub">${BB.lanes[origin].hub} → Dhaka</strong><small>Your global shopping connection</small></div></div><div class="floating-label hero-arrived"><span class="round-icon">✓</span><div><strong>A little closer to home.</strong><small>Every step, in one place · simulated</small></div></div></div></section>
    <section class="markets-strip" aria-label="Source markets"><div class="markets-inner"><span>Big possibilities.<br>Beyond borders.</span><div class="market-switches">${countries.map(c=>`<button data-action="market" data-id="${c}" class="${c===origin?'active':''}" aria-pressed="${c===origin}"><span class="flag">${flags[c]}</span>${c}<span>↗</span></button>`).join('')}</div><span class="country-end">Delivered to <i></i> Bangladesh</span></div></section>
    <section class="section container"><div class="section-head"><div><div class="eyebrow">The global edit</div><h2>Good finds. No boundaries.</h2></div><a class="text-link" href="#shop">Explore all products ${arrow}</a></div><div class="products-grid">${cards([seed.products[0],seed.products[3],seed.products[1],seed.products[5]])}</div><div class="collection-bar"><span>Something in mind? Let our shopping proxy handle the journey.</span><button data-action="proxy">Try “Buy for me” ${arrow}</button></div></section>
    <section class="section services-section" id="services"><div class="container"><div class="section-head"><div><div class="eyebrow">One bridge. Every possibility.</div><h2>Your world, connected.</h2></div><p>From your first global find to the final mile.<br>A simpler way to shop across borders.</p></div><div class="services-grid"><article class="service-card"><span class="service-index">01 / SHOPPING PROXY</span>${icon('bag','service-icon')}<h3>You choose. We shop.</h3><p>Found something overseas? Explore how a shopping proxy purchases and forwards it on your behalf.</p><button class="text-link" data-action="proxy" data-id="buy">Buy for me ${arrow}</button></article><article class="service-card"><span class="service-index">02 / FREIGHT FORWARDING</span>${icon('box','service-icon')}<h3>Your parcel. Our journey.</h3><p>See how a parcel moves from an origin hub to Bangladesh, with every milestone in one timeline.</p><button class="text-link" data-action="proxy" data-id="ship">Ship for me ${arrow}</button></article><article class="service-card"><span class="service-index">03 / BUSINESS SOURCING</span>${icon('globe','service-icon')}<h3>Think bigger. Source smarter.</h3><p>Walk through a small-batch sourcing request and compare the illustrative cost of air and sea freight.</p><button class="text-link" data-action="proxy" data-id="business">Explore sourcing ${arrow}</button></article></div></div></section>
    <section class="section container" id="how"><div class="how-grid"><div class="how-visual"><span>GLOBAL FINDS. LOCAL DOORSTEPS.</span><div class="route-graphic"><div class="route-city"><small>ORIGIN HUB</small><strong id="how-hub">${BB.lanes[origin].hub}</strong></div><div class="route-plane">✈</div><div class="route-city"><small>HOME SWEET HOME</small><strong>Dhaka, BD</strong></div></div><div class="how-caption">Less distance.<br>More possibilities.<small>Illustrative route · no real logistics operations</small></div></div><div class="how-content"><div class="eyebrow">Simple from the very first click</div><h2 class="section-title">A world of shopping.<br>Three simple steps.</h2><p>From “I love that” to “It’s here.” Follow a sample order through the complete cross-border experience.</p><div class="steps"><div class="step"><span class="step-number">01</span><div><h3>Find your next favorite</h3><p>Browse our fictional global catalog or try a proxy request.</p></div></div><div class="step"><span class="step-number">02</span><div><h3>Know the journey. See the cost.</h3><p>Compare sample shipping rates and a clear cost breakdown in taka.</p></div></div><div class="step"><span class="step-number">03</span><div><h3>Follow it all the way home</h3><p>Create a demo order and explore every shipping milestone.</p></div></div></div></div></div></section>
    <section class="section estimator-section container" id="estimator">${estimatorHTML('inline')}</section>
    <section class="section faq-section container"><div class="faq-layout"><div class="faq-intro"><div class="eyebrow">A little clarity</div><h2 class="section-title">Good questions.<br>Simple answers.</h2><p>Everything to know before exploring the demo.</p></div><div class="faq-list"><details><summary>What is a shopping proxy?</summary><p>A shopping proxy purchases an item from an overseas store on a shopper’s behalf, then arranges forwarding. This project simulates that workflow using fictional products and locally stored orders.</p></details><details><summary>Can I place a real order here?</summary><p>This is an MIS 465 educational project. Every purchase, product, price, and shipping event is simulated. No money is collected, no supplier is contacted, and no parcel is shipped.</p></details><details><summary>How is the estimated total calculated?</summary><p>The classroom formula combines product cost at a fixed fictional exchange rate, freight rounded up to half a kilogram, a 5% service fee, a 15% illustrative duty allowance, and a mock delivery fee. These are not real rates or customs advice.</p></details><details><summary>Where is my demo data saved?</summary><p>Only in this browser using local storage. There are no accounts, passwords, analytics, or server database. Use preset dummy information only. Reset demo data from the footer to start again.</p></details></div></div></section>
    <section class="cta-band"><div><h2>Your next favorite is out there.</h2><p>Let’s bring a world of possibilities a little closer.</p></div><a class="button dark" href="#shop">Start exploring ${arrow}</a></section>`;
    bindEstimator('inline');
  }
  function estimatorHTML(prefix) { return `<div class="estimator"><div class="estimator-input"><div class="eyebrow">No surprises. Just possibilities.</div><h2 ${prefix==='modal'?'id="modal-title"':''}>A clearer picture of the cost.</h2><p>Try a sample landed-cost estimate. All rates and charges are invented for this course demo.</p><form id="${prefix}-estimate"><div class="form-grid"><div class="field"><label for="${prefix}-origin">Shopping from</label><select id="${prefix}-origin" name="origin">${options(countries,origin)}</select></div><div class="field"><label for="${prefix}-mode">Shipping method</label><select id="${prefix}-mode" name="mode"><option value="air">Air freight · demo</option><option value="sea">Sea freight · demo</option></select></div><div class="field"><label for="${prefix}-price">Item value (USD)</label><input id="${prefix}-price" name="price" type="number" min="0" max="100000" step="0.01" value="42" required></div><div class="field"><label for="${prefix}-weight">Parcel weight (kg)</label><input id="${prefix}-weight" name="weight" type="number" min="0.01" max="1000" step="0.01" value="0.5" required></div><div class="field"><label for="${prefix}-city">Delivering to</label><select id="${prefix}-city" name="city">${options(BB.cities,'Dhaka')}</select></div><div class="field"><label for="${prefix}-quantity">Quantity</label><input id="${prefix}-quantity" name="quantity" type="number" min="1" max="20" step="1" value="1" required></div></div><button class="button dark modal-submit" type="submit">Update estimate ${arrow}</button><p class="form-error" id="${prefix}-error" role="alert" hidden></p></form></div><div class="estimator-result" id="${prefix}-result" aria-live="polite"></div></div>`; }
  function bindEstimator(prefix) { const form=$(`#${prefix}-estimate`); const update=()=>{try{if(!form.checkValidity())return;const result=BB.estimate(Object.fromEntries(new FormData(form))); $(`#${prefix}-result`).innerHTML=resultHTML(result);$(`#${prefix}-error`).hidden=true;}catch(e){$(`#${prefix}-error`).textContent=e.message;$(`#${prefix}-error`).hidden=false;}};form.addEventListener('submit',e=>{e.preventDefault();update();});form.addEventListener('change',update);update(); }
  function resultHTML(r) {return `<div><p class="result-caption">ILLUSTRATIVE LANDED TOTAL</p><div class="estimate-total">${money(r.total)}</div><p class="estimate-time">${r.days} sample transit days · ${r.billableWeight} kg billable</p><div class="cost-lines"><div class="cost-line"><span>Product value · mock $1 = ৳120</span><span>${money(r.items)}</span></div><div class="cost-line"><span>International shipping</span><span>${money(r.shipping)}</span></div><div class="cost-line"><span>Service fee · 5%</span><span>${money(r.service)}</span></div><div class="cost-line"><span>Illustrative duty allowance · 15%</span><span>${money(r.duties)}</span></div><div class="cost-line"><span>Local delivery</span><span>${money(r.delivery)}</span></div><div class="cost-line cost-total"><span>Demo total</span><span>${money(r.total)}</span></div></div></div><p class="estimate-caution">Classroom illustration only. Not a quote, live exchange rate, or customs calculation. No amount is payable.</p>`;}
  function shopPage(){main.innerHTML=`<section class="container shop-section"><div class="shop-heading"><div class="eyebrow">The global edit · all fictional</div><h1>A little discovery.<br>A world of favorites.</h1><p>Explore 12 curated sample finds from four markets. Item prices shown in taka; freight is estimated separately.</p></div><div class="shop-toolbar"><div class="search-wrap">${icon('search')}<label class="sr-only" for="shop-search">Search products</label><input id="shop-search" type="search" placeholder="Search products or brands…" maxlength="80" value="${esc(shop.query)}"></div><label class="sr-only" for="shop-origin">Filter by origin</label><select id="shop-origin">${options(['All origins',...countries],shop.origin)}</select><label class="sr-only" for="shop-sort">Sort products</label><select id="shop-sort"><option value="featured">Featured finds</option><option value="low">Price: low to high</option><option value="high">Price: high to low</option><option value="light">Lightest first</option></select></div><div class="category-tabs" role="group" aria-label="Product category">${categories.map(c=>`<button data-action="category" data-id="${c}" class="${c===shop.category?'active':''}" aria-pressed="${c===shop.category}">${c}</button>`).join('')}</div><p id="shop-count" class="result-count" aria-live="polite"></p><div id="shop-products" class="products-grid"></div><div class="collection-bar"><span>Every brand and product in this catalog is generated for this demo.</span><button data-action="proxy">Create a proxy request ${arrow}</button></div></section>`;$('#shop-sort').value=shop.sort;$('#shop-search').addEventListener('input',e=>{shop.query=e.target.value;filterProducts();});$('#shop-origin').addEventListener('change',e=>{shop.origin=e.target.value;filterProducts();});$('#shop-sort').addEventListener('change',e=>{shop.sort=e.target.value;filterProducts();});filterProducts();}
  function filterProducts(){let list=seed.products.filter(p=>(shop.category==='All products'||p.category===shop.category)&&(shop.origin==='All origins'||p.origin===shop.origin)&&`${p.name} ${p.brand} ${p.category}`.toLowerCase().includes(shop.query.toLowerCase().trim()));if(shop.sort==='low')list.sort((a,b)=>a.price-b.price);if(shop.sort==='high')list.sort((a,b)=>b.price-a.price);if(shop.sort==='light')list.sort((a,b)=>a.weight-b.weight);$('#shop-count').textContent=`${list.length} sample ${list.length===1?'product':'products'} · generated catalog`;$('#shop-products').innerHTML=list.length?cards(list):`<div class="empty-state"><h3>No finds just yet.</h3><p>Try another search, category, or source market.</p><button class="button dark" data-action="clear-filters">Clear filters</button></div>`;$('.category-tabs').querySelectorAll('button').forEach(b=>{b.classList.toggle('active',b.dataset.id===shop.category);b.setAttribute('aria-pressed',b.dataset.id===shop.category);});}
  function dashboardPage(){const total=state.orders.length,delivered=state.orders.filter(o=>o.statusIndex===5).length;main.innerHTML=`<section class="container"><div class="dashboard-heading"><div><div class="eyebrow">Your demo workspace</div><h1>Every journey, in view.</h1><p>Explore generated orders and follow each sample parcel home.</p></div><button class="button dark" data-action="proxy">New proxy request ${arrow}</button></div><div class="dashboard-stats"><div class="stat-card"><span>Sample orders</span><strong>${total}</strong><small>Stored in this browser</small></div><div class="stat-card"><span>Active journeys</span><strong>${total-delivered}</strong><small>Before simulated delivery</small></div><div class="stat-card"><span>Delivered</span><strong>${delivered}</strong><small>Fictional parcel milestones</small></div><div class="stat-card"><span>Real money collected</span><strong>৳0</strong><small>Educational demo only</small></div></div><div class="dashboard-panel"><div class="panel-head"><div><h2>Parcel activity</h2><p>${viewAdmin?'Demo admin · advance each order one step at a time':'Shopper view · all records are generated examples'}</p></div><button class="button small outline" data-action="admin" aria-pressed="${viewAdmin}">${viewAdmin?'Exit demo admin':'Enter demo admin'} ${arrow}</button></div><div class="table-toolbar"><div class="search-wrap">${icon('search')}<label class="sr-only" for="order-search">Search orders</label><input type="search" id="order-search" placeholder="Search a demo ID or product…" maxlength="80" value="${esc(dash.query)}"></div><label class="sr-only" for="order-status">Order status</label><select id="order-status"><option value="all">All statuses</option>${BB.statuses.map((s,i)=>`<option value="${i}">${s}</option>`).join('')}</select></div><div class="table-scroll"><table><thead><tr><th>Order / product</th><th>Route</th><th>Demo total</th><th>Status</th><th>Action</th></tr></thead><tbody id="order-rows"></tbody></table></div><p class="admin-note">${viewAdmin?'Demo admin is an open classroom simulator, with no authentication or real administrative privileges. “Next step” changes only this browser’s dummy data.':'Try the demo admin view to simulate purchasing, origin handling, international transit, customs, and delivery. No carrier is connected.'}</p></div><div class="dashboard-bottom"><span>Session data is local to this browser. No account or personal information needed.</span><button class="text-link" data-action="export">Export dummy orders ${arrow}</button></div></section>`;$('#order-status').value=dash.status;$('#order-search').addEventListener('input',e=>{dash.query=e.target.value;orderRows();});$('#order-status').addEventListener('change',e=>{dash.status=e.target.value;orderRows();});orderRows();}
  function orderRows(){const list=state.orders.filter(o=>(dash.status==='all'||String(o.statusIndex)===dash.status)&&`${o.id} ${product(o.productId)?.name||o.productName}`.toLowerCase().includes(dash.query.toLowerCase().trim())).slice().reverse();$('#order-rows').innerHTML=list.length?list.map(o=>`<tr><td><strong>${esc(o.id)}</strong><small>${esc(product(o.productId)?.name||o.productName||'Sample proxy request')} × ${o.quantity}</small></td><td>${flags[o.origin]||flags[product(o.productId)?.origin]||'🌐'} ${esc(o.origin||product(o.productId)?.origin||'China')} → BD<small>${esc(o.city)}</small></td><td>${money(o.amount)}<small>No payment due</small></td><td><span class="status-chip ${o.statusIndex===5?'green':''}">${BB.statuses[o.statusIndex]}</span></td><td><button class="table-action" data-action="track-order" data-id="${esc(o.id)}">View journey ↗</button>${viewAdmin?` <button class="table-action" data-action="advance" data-id="${esc(o.id)}" ${o.statusIndex===5?'disabled':''}>${o.statusIndex===5?'Complete':'Next step →'}</button>`:''}</td></tr>`).join(''):`<tr><td colspan="5" style="text-align:center;padding:45px">No matching sample orders. Try a different filter.</td></tr>`;}
  function navigate(){const hash=location.hash.slice(1)||'home';route=hash.split('/')[0];if(!['home','shop','dashboard'].includes(route))route='home';if(modal.open)modal.close();$('#mobile-nav').hidden=true;$('.menu-button').setAttribute('aria-expanded','false');document.querySelectorAll('[data-route]').forEach(a=>a.classList.toggle('active',a.dataset.route===route));if(route==='home')homePage();if(route==='shop')shopPage();if(route==='dashboard')dashboardPage();updateBag();const target=hash.split('/')[1];if(target)document.getElementById(target)?.scrollIntoView({behavior:'instant'});else window.scrollTo(0,0);document.title=`${route==='home'?'The world, delivered home.':route==='shop'?'Shop global':'Demo dashboard'} — BongoBridge | MIS 465`;}
  function openModal(html,{drawer=false,wide=false}={}){const wasOpen=modal.open;if(!wasOpen)lastFocus=document.activeElement;modal.className=drawer?'drawer':'';modal.style.width=wide?'min(970px,94vw)':'';content.innerHTML=html;if(!wasOpen)modal.showModal();else $('.modal-close').focus();}
  function showProduct(id){const p=product(id);if(!p)return;const r=BB.estimate({...p,quantity:1,city:'Dhaka',mode:'air'});openModal(`<p class="modal-eyebrow">${esc(p.brand)} · ${flags[p.origin]} ${p.origin}</p><div class="product-detail-art" style="background:${p.accent}">${art(p)}</div><h2 id="modal-title">${esc(p.name)}</h2><p class="modal-intro">${esc(p.description)}</p><div class="detail-meta"><strong>${money(p.price*120)} item only</strong><span>${p.weight} kg sample weight</span></div><div class="form-note">Illustrative landed total to Dhaka: <strong>${money(r.total)}</strong> by air. Includes mock freight, fees, duty allowance, and delivery. No amount payable.</div><button class="button dark modal-submit" data-action="add" data-id="${p.id}">Add to demo bag +</button>`);}
  function addToBag(id){const p=product(id);if(!p)return;const found=state.cart.find(i=>i.productId===id);if(found&&found.quantity>=20){toast('Demo limit: 20 of each sample product.');return;}if(found)found.quantity++;else state.cart.push({productId:id,quantity:1});saveAndToast(`${p.name} added to your demo bag.`);if(modal.open&&modal.classList.contains('drawer'))showBag();}
  function showBag(){const subtotal=state.cart.reduce((a,i)=>a+product(i.productId).price*120*i.quantity,0);openModal(`<p class="modal-eyebrow">A few global favorites</p><h2 id="modal-title">Your demo bag<span style="color:#8fa679">.</span></h2>${state.cart.length?`${state.cart.map(i=>{const p=product(i.productId);return `<div class="bag-item"><div class="bag-thumb" style="background:${p.accent}">${art(p)}</div><div><h3>${esc(p.name)}</h3><p>${flags[p.origin]} ${p.origin} · ${money(p.price*120)}</p><div class="quantity-controls"><button data-action="qty-minus" data-id="${p.id}" aria-label="Decrease ${esc(p.name)} quantity">−</button><span aria-label="Quantity">${i.quantity}</span><button data-action="qty-plus" data-id="${p.id}" aria-label="Increase ${esc(p.name)} quantity" ${i.quantity>=20?'disabled':''}>+</button></div></div><button class="remove-item" data-action="remove" data-id="${p.id}" aria-label="Remove ${esc(p.name)}">×</button></div>`;}).join('')}<div class="bag-subtotal"><span>Items subtotal</span><strong>${money(subtotal)}</strong></div><p class="modal-intro">Sample freight and charges are calculated in the next step. No real payment, address, or account is needed.</p><button class="button dark modal-submit" data-action="checkout">Continue to demo checkout ${arrow}</button>`:`<div class="empty-state"><h3>Your next favorite awaits.</h3><p>Add a fictional product to explore the complete shopping journey.</p><a class="button dark" href="#shop" data-action="close-link">Explore global finds ${arrow}</a></div>`}<div class="form-note">MIS 465 simulation · all items are fictional. No real transaction can take place.</div>`,{drawer:true});}
  function checkout(){if(!state.cart.length)return showBag();openModal(`<p class="modal-eyebrow">One step closer · simulation only</p><h2 id="modal-title">Make it a demo journey.</h2><p class="modal-intro">Your shopper is preset as <strong>Demo Shopper</strong>. Select a city and a shipping method; no personal or payment details are collected.</p><form id="checkout-form"><div class="form-grid"><div class="field"><label for="checkout-city">Sample delivery city</label><select id="checkout-city" name="city">${options(BB.cities,'Dhaka')}</select></div><div class="field"><label for="checkout-mode">Shipping method</label><select id="checkout-mode" name="mode"><option value="air">Air freight · demo</option><option value="sea">Sea freight · demo</option></select></div></div><div class="checkout-summary" id="checkout-totals" aria-live="polite"></div><p class="form-note">Each product becomes its own sample parcel. Freight and delivery are calculated per parcel; consolidation is not simulated. Nothing will be charged.</p><button class="button dark modal-submit" type="submit">Create mock orders ${arrow}</button></form>`);const form=$('#checkout-form');const update=()=>{const data=Object.fromEntries(new FormData(form));const totals=state.cart.map(i=>{const p=product(i.productId);return {p,...BB.estimate({...p,...data,quantity:i.quantity})};});$('#checkout-totals').innerHTML=totals.map(r=>`<div class="checkout-line"><span>${esc(r.p.name)}</span><span>${money(r.total)}</span></div>`).join('')+`<div class="checkout-line"><span>Illustrative total</span><span>${money(totals.reduce((a,r)=>a+r.total,0))}</span></div>`;};form.addEventListener('change',update);form.addEventListener('submit',e=>{e.preventDefault();if(!state.cart.length)return;const data=Object.fromEntries(new FormData(form));const made=[];for(const i of state.cart){const p=product(i.productId);const o=BB.makeOrder({...p,...data,product:p,quantity:i.quantity,orders:state.orders});state.orders.push(o);made.push(o);}state.cart=[];persist();showSuccess(made);});update();}
  function proxy(kind='buy'){const titles={buy:'Found it? Let’s bridge the gap.',ship:'Let’s give your parcel a journey.',business:'A small batch. A big possibility.'};kind=Object.hasOwn(titles,kind)?kind:'buy';openModal(`<p class="modal-eyebrow">${kind==='ship'?'Freight forwarding':kind==='business'?'Business sourcing':'Buy for me'} · demo request</p><h2 id="modal-title">${titles[kind]}</h2><p class="modal-intro">Choose a generated item to simulate a ${kind==='ship'?'forwarding':kind==='business'?'sourcing':'shopping proxy'} request. ${kind==='ship'?'The estimator uses the declared sample item value; this demo creates an end-to-end proxy record.':'We use presets in place of real store links and customer details.'}</p><form id="proxy-form"><div class="field"><label for="proxy-product">Sample item</label><select id="proxy-product" name="productId">${seed.products.map(p=>`<option value="${p.id}">${esc(p.name)} · ${p.origin}</option>`).join('')}</select></div><div class="form-grid" style="margin-top:18px"><div class="field"><label for="proxy-quantity">Quantity</label><input id="proxy-quantity" name="quantity" type="number" min="1" max="20" step="1" value="${kind==='business'?5:1}" required></div><div class="field"><label for="proxy-city">Sample delivery city</label><select id="proxy-city" name="city">${options(BB.cities,'Dhaka')}</select></div><div class="field"><label for="proxy-mode">Shipping method</label><select id="proxy-mode" name="mode"><option value="air">Air freight · demo</option><option value="sea">Sea freight · demo</option></select></div><div class="field"><label for="proxy-persona">Shopper</label><select id="proxy-persona" disabled><option>Demo Shopper (preset)</option></select></div></div><div class="checkout-summary" id="proxy-totals" aria-live="polite"></div><p class="form-note">All figures are invented. This creates a browser-local record only. No supplier, carrier, or payment service will be contacted.</p><p class="form-error" id="proxy-error" role="alert" hidden></p><button class="button dark modal-submit" type="submit">Create demo request ${arrow}</button></form>`);const form=$('#proxy-form');const update=()=>{if(!form.checkValidity())return;try{const data=Object.fromEntries(new FormData(form));const p=product(data.productId),r=BB.estimate({...p,...data});$('#proxy-totals').innerHTML=`<div class="checkout-line"><span>${flags[p.origin]} ${p.origin} → ${esc(data.city)}</span><span>${r.days} sample days</span></div><div class="checkout-line"><span>Illustrative total</span><span>${money(r.total)}</span></div>`;$('#proxy-error').hidden=true;}catch(e){$('#proxy-error').textContent=e.message;$('#proxy-error').hidden=false;}};form.addEventListener('change',update);form.addEventListener('input',update);form.addEventListener('submit',e=>{e.preventDefault();try{const data=Object.fromEntries(new FormData(form)),p=product(data.productId);const o=BB.makeOrder({...p,...data,product:p,orders:state.orders});state.orders.push(o);persist();showSuccess([o]);}catch(e){$('#proxy-error').textContent=e.message;$('#proxy-error').hidden=false;}});update();}
  function showSuccess(orders){openModal(`<div class="success-icon">✓</div><p class="modal-eyebrow">A new journey, imagined</p><h2 id="modal-title">Your mock ${orders.length===1?'order is':'orders are'} on the map.</h2><p class="modal-intro">${orders.length===1?'One sample request has':`${orders.length} sample requests have`} been saved in this browser. No purchase was made and no payment is due.</p><div class="success-id">${orders.map(o=>esc(o.id)).join('<br>')}</div><button class="button dark modal-submit" data-action="track-order" data-id="${orders[0].id}">Follow the sample journey ${arrow}</button><a class="button outline modal-submit" href="#dashboard" data-action="close-link">View demo dashboard ${arrow}</a>`);if(route==='dashboard')dashboardPage();}
  function tracking(id){openModal(`<p class="modal-eyebrow">From there to here</p><h2 id="modal-title">A little closer with every step.</h2><p class="modal-intro">Follow a fictional parcel. Try <strong>BB-DEMO-1044</strong> or enter an ID created in this browser.</p><form id="track-form"><div class="field"><label for="tracking-id">Demo tracking ID</label><input id="tracking-id" name="tracking" placeholder="BB-DEMO-1044" value="${esc(id||'')}" maxlength="30" required autocomplete="off" spellcheck="false" pattern="[Bb][Bb]-[Dd][Ee][Mm][Oo]-[0-9]{4,}" title="Use a demo ID such as BB-DEMO-1044"></div><button class="button dark modal-submit" type="submit">Track sample parcel ${arrow}</button><p class="form-error" id="track-error" role="alert" hidden></p></form><div id="track-result" aria-live="polite"></div>`);const form=$('#track-form');form.addEventListener('submit',e=>{e.preventDefault();renderTracking($('#tracking-id').value.trim().toUpperCase());});if(id)renderTracking(id);}
  function renderTracking(id){const o=state.orders.find(o=>o.id===id);$('#track-error').hidden=!!o;if(!o){$('#track-error').textContent='That sample ID was not found in this browser. Try BB-DEMO-1044.';$('#track-result').innerHTML='';return;}const p=product(o.productId);$('#track-result').innerHTML=`<div class="tracker-summary"><div><strong>${esc(o.id)}</strong><small>${esc(p?.name||o.productName)}</small></div><div><strong>${esc(o.city)}, BD</strong><small>${flags[o.origin||p?.origin]||'🌐'} From ${esc(o.origin||p?.origin||'China')}</small></div></div><div class="timeline">${BB.statuses.map((s,i)=>`<div class="timeline-step ${i<o.statusIndex?'complete':i===o.statusIndex?'current':''}" ${i===o.statusIndex?'aria-current="step"':''}><h3>${s} ${i<o.statusIndex?'✓':i===o.statusIndex?'· Current':''}</h3><p>${['Sample request saved locally.','Simulated overseas purchase completed.','Sample parcel checked into the origin hub.','Fictional international transport is in progress.','Illustrative customs milestone; no real clearance.','Simulated delivery to the preset city.'][i]}</p></div>`).join('')}</div><p class="form-note">Simulated events, not live carrier updates. Visit the demo admin view to move an order to its next step.</p><a href="#dashboard" class="text-link" data-action="close-link">Open demo dashboard ${arrow}</a>`;}
  function about(){openModal(`<p class="modal-eyebrow">Built for learning</p><h2 id="modal-title">A bridge between ideas and practice.</h2><p class="modal-intro">BongoBridge is an original cross-border commerce simulation for an MIS 465 web development course, focused on the Bangladesh shopping and freight-forwarding experience.</p><ul class="project-list"><li>12 generated products, four fictional routes, and six seeded orders.</li><li>Shopping bag, cost estimator, proxy requests, shipment milestones, and an open demo admin view.</li><li>Only browser-local storage. No server, account, payment integration, analytics, or external API calls.</li><li>No personal details are requested. Use the preset sample shopper and cities.</li><li>All prices, duty allowances, brands, and shipping dates are invented and are not guidance for real imports.</li><li>Inspired by the concept of end-to-end commerce; not affiliated with Baozun or any marketplace.</li></ul><p class="form-note">This static app needs no subscription, database account, credit card, or API key. The optional SQL schema is a separate teaching resource and is not connected to this site.</p><button class="button dark modal-submit" data-action="close">Keep exploring ${arrow}</button>`);}
  function resetPrompt(){openModal(`<p class="modal-eyebrow">A fresh start</p><h2 id="modal-title">Reset this classroom demo?</h2><p class="modal-intro">This clears your bag and locally created mock orders, then restores the six generated examples. Only BongoBridge demo data in this browser is affected.</p><button class="button dark modal-submit" data-action="reset-confirm">Reset demo data ${arrow}</button><button class="button outline modal-submit" data-action="close">Keep my demo session</button>`);}
  function exportData(kind='orders'){const data=kind==='seed'?seed:{purpose:'MIS 465 educational demo only. All records fictional. No real transactions.',...state};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=kind==='seed'?'bongobridge-generated-database.json':'bongobridge-demo-orders.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Dummy data exported as JSON.');}
  document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const id=el.dataset.id;switch(el.dataset.action){case'menu':$('#mobile-nav').hidden=!$('#mobile-nav').hidden;el.setAttribute('aria-expanded',!$('#mobile-nav').hidden);break;case'close':modal.close();break;case'close-link':modal.close();break;case'about':about();break;case'seed':e.preventDefault();exportData('seed');break;case'reset':resetPrompt();break;case'reset-confirm':{const fresh=BB.reset(seed);state.orders=fresh.orders;state.cart=fresh.cart;modal.close();dash={query:'',status:'all'};navigate();toast('Demo reset. Six sample orders restored.');break;}case'product':showProduct(id);break;case'add':e.stopPropagation();addToBag(id);break;case'bag':showBag();break;case'qty-plus':{const i=state.cart.find(x=>x.productId===id);if(i&&i.quantity<20)i.quantity++;persist();showBag();break;}case'qty-minus':{const i=state.cart.find(x=>x.productId===id);if(i&&i.quantity>1)i.quantity--;else state.cart.splice(state.cart.indexOf(i),1);persist();showBag();break;}case'remove':state.cart.splice(state.cart.findIndex(x=>x.productId===id),1);persist();showBag();break;case'checkout':checkout();break;case'proxy':proxy(id);break;case'track':tracking();break;case'track-order':tracking(id);break;case'estimate':openModal(estimatorHTML('modal'),{wide:true});bindEstimator('modal');break;case'market':origin=id;document.querySelectorAll('[data-action="market"]').forEach(b=>{b.classList.toggle('active',b.dataset.id===origin);b.setAttribute('aria-pressed',b.dataset.id===origin);});$('#hero-flag').textContent=flags[origin];$('#hero-hub').textContent=BB.lanes[origin].hub+' → Dhaka';$('#how-hub').textContent=BB.lanes[origin].hub;$('#inline-origin').value=origin;$('#inline-origin').dispatchEvent(new Event('change',{bubbles:true}));break;case'category':shop.category=id;filterProducts();break;case'clear-filters':shop={category:'All products',origin:'All origins',sort:'featured',query:''};shopPage();break;case'admin':viewAdmin=!viewAdmin;dashboardPage();break;case'advance':{const o=state.orders.find(o=>o.id===id);if(o&&o.statusIndex<5){o.statusIndex++;persist();dashboardPage();toast(`${o.id}: ${BB.statuses[o.statusIndex]}`);}break;}case'export':exportData();break;}});
  modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
  modal.addEventListener('close',()=>{if(lastFocus?.isConnected)lastFocus.focus();});
  window.addEventListener('hashchange',navigate);
  $('#seed-link').setAttribute('data-action','seed');$('#seed-link').removeAttribute('href');$('#seed-link').setAttribute('role','button');$('#seed-link').setAttribute('tabindex','0');$('#seed-link').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();exportData('seed');}});
  updateBag();navigate();
})();
